package com.celik.kingdoms;

import java.nio.file.Path;
import java.util.*;
import org.junit.jupiter.api.Test;
import static com.celik.kingdoms.Rules.*;
import static org.junit.jupiter.api.Assertions.*;

class DiplomacyRulesTest {
    State s=new State();Store store=new Store(Path.of("unused"));
    Kingdom kingdom(String name){Kingdom k=new Kingdom();k.name=name;UUID mayor=UUID.randomUUID();k.members.put(mayor,name);k.mayors.add(mayor);k.claims.add("minecraft:overworld|"+s.kingdoms.size()+"|0");s.kingdoms.put(k.id,k);return k;}
    UUID mayor(Kingdom k){return k.mayors.iterator().next();}
    void ally(Kingdom a,Kingdom b){a.allies.add(b.id);b.allies.add(a.id);}
    War war(Kingdom a,Kingdom b){War w=new War();w.first=a.id;w.second=b.id;w.declaredAt=100;w.startedAt=500;w.endsAt=1000;w.cooldownMillis=200;s.wars.add(w);return w;}
    @Test void allOpponentsCanUseClaimsOnlyDuringActiveWar(){Kingdom a=kingdom("A"),b=kingdom("B"),c=kingdom("C"),d=kingdom("D"),neutral=kingdom("Neutral");ally(a,c);ally(b,d);War w=war(a,b);w.firstAllies.add(c.id);w.secondAllies.add(d.id);for(Kingdom land:List.of(a,c))for(Kingdom enemy:List.of(b,d)){assertFalse(permitted(s,land,mayor(enemy),Permission.BREAK,499));assertTrue(permitted(s,land,mayor(enemy),Permission.BREAK,500));assertTrue(Rules.enemy(s,land,mayor(enemy),500));assertFalse(permitted(s,land,mayor(enemy),Permission.BREAK,1000));assertFalse(permitted(s,land,mayor(enemy),Permission.WITHDRAW,500));}assertFalse(permitted(s,c,mayor(neutral),Permission.BREAK,500));}
    @Test void sameSideRequiresExplicitBuildingPermission(){Kingdom a=kingdom("A"),b=kingdom("B"),c=kingdom("C");ally(a,c);War w=war(a,b);w.firstAllies.add(c.id);assertFalse(Rules.enemy(s,a,mayor(c),600));assertFalse(permitted(s,a,mayor(c),Permission.BREAK,600));a.grants.put(mayor(c),Set.of(Permission.BREAK));assertTrue(permitted(s,a,mayor(c),Permission.BREAK,600));assertFalse(permitted(s,a,mayor(c),Permission.PLACE,600));}
    @Test void coalitionMembershipFreezesAndFlagsApplyToEveryParticipant(){Kingdom a=kingdom("A"),b=kingdom("B"),c=kingdom("C");War w=war(a,b);w.firstAllies.add(c.id);assertNotNull(conflict(s,c.id,200));assertNull(Rules.war(s,c.id,200));assertNotNull(Rules.war(s,c.id,500));assertTrue(flag(s,c,Flag.EXPLOSIONS,500));assertFalse(flag(s,c,Flag.EXPLOSIONS,1000));assertNotNull(declarationFailure(s,c,b,mayor(c),Set.of(mayor(b)),200));}
    @Test void joinChecksProtectionCooldownOtherWarsOnlineCountAndExactStart(){Kingdom a=kingdom("A"),b=kingdom("B"),c=kingdom("C");War w=war(a,b);Set<UUID> online=Set.of(mayor(c));assertNull(warJoinFailure(s,w,c,true,4,true,online,200));c.protectedUntil=300;assertNotNull(warJoinFailure(s,w,c,true,4,true,online,200));c.protectedUntil=0;c.cooldownUntil=300;assertNotNull(warJoinFailure(s,w,c,true,4,true,online,200));c.cooldownUntil=0;assertNotNull(warJoinFailure(s,w,c,true,1,true,online,200));assertNotNull(warJoinFailure(s,w,c,true,4,true,Set.of(),200));assertNull(warJoinFailure(s,w,c,true,4,false,Set.of(),200));assertNotNull(warJoinFailure(s,w,c,true,4,true,online,500));war(c,kingdom("D"));assertNotNull(warJoinFailure(s,w,c,true,4,true,online,200));}
    @Test void alliancesCannotBeUsedAgainstAlliesOrToCrossSides(){Kingdom a=kingdom("A"),b=kingdom("B"),c=kingdom("C");ally(a,b);assertNotNull(declarationFailure(s,a,b,mayor(a),Set.of(mayor(b)),200));a.allies.clear();b.allies.clear();War w=war(a,b);ally(b,c);assertNotNull(warJoinFailure(s,w,c,true,4,true,Set.of(mayor(c)),200));assertNull(warJoinFailure(s,w,c,false,4,true,Set.of(mayor(c)),200));}
    @Test void legacyPairWarsAndNewCoalitionsRoundTripWithoutChangingTimes(){Kingdom a=kingdom("A"),b=kingdom("B"),c=kingdom("C");War w=war(a,b);var json=Store.JSON.toJsonTree(s).getAsJsonObject();json.remove("allianceRequests");json.remove("warInvites");var old=json.getAsJsonArray("wars").get(0).getAsJsonObject();old.remove("firstAllies");old.remove("secondAllies");for(var kingdom:json.getAsJsonObject("kingdoms").entrySet())kingdom.getValue().getAsJsonObject().remove("allies");State loaded=Store.JSON.fromJson(json,State.class);store.validate(loaded);War restored=loaded.wars.getFirst();assertEquals(2,restored.participants().size());assertEquals(w.startedAt,restored.startedAt);w.secondAllies.add(c.id);State copy=store.copy(s);store.validate(copy);assertTrue(copy.wars.getFirst().opposes(a.id,c.id));assertEquals(w.endsAt,copy.wars.getFirst().endsAt);}
    @Test void invalidSidesAndAsymmetricAlliancesFailClosed(){Kingdom a=kingdom("A"),b=kingdom("B"),c=kingdom("C");a.allies.add(c.id);assertThrows(IllegalStateException.class,()->store.validate(s));c.allies.add(a.id);store.validate(s);War w=war(a,b);w.firstAllies.add(c.id);store.validate(s);w.secondAllies.add(c.id);assertThrows(IllegalStateException.class,()->store.validate(s));}
    @Test void enrolledAlliesReceiveSharedCooldownAndMemberCooldown(){Kingdom a=kingdom("A"),b=kingdom("B"),c=kingdom("C");War w=war(a,b);w.firstAllies.add(c.id);KingdomDiplomacy.enroll(s,w,c.id);assertEquals(1200,c.cooldownUntil);assertEquals(1200,s.playerCooldowns.get(mayor(c)));}
    @Test void disbandCleansAlliancesRequestsAndUnacceptedInvites(){Kingdom a=kingdom("A"),b=kingdom("B"),c=kingdom("C");ally(a,c);War w=war(a,b);AllianceRequest r=new AllianceRequest();r.from=c.id;r.to=b.id;r.expiresAt=800;s.allianceRequests.add(r);WarInvite i=new WarInvite();i.from=a.id;i.to=c.id;i.war=w.id;i.attacking=true;s.warInvites.add(i);s.kingdoms.remove(c.id);KingdomDiplomacy.removeKingdom(s,c.id);store.validate(s);assertTrue(a.allies.isEmpty());assertTrue(s.allianceRequests.isEmpty());assertTrue(s.warInvites.isEmpty());}
    @Test void homeMigrationPreservesBeaconAndCustomSlots(){Config config=new Config();config.validate();assertEquals(30,config.menuSlots.get("protection"));assertEquals(32,config.menuSlots.get("beacon"));assertEquals(40,config.menuSlots.get("alliances"));Config custom=new Config();custom.menuSlots.put("settings",40);custom.validate();assertEquals(40,custom.menuSlots.get("settings"));assertNotEquals(40,custom.menuSlots.get("alliances"));assertEquals(new HashSet<>(custom.menuSlots.values()).size(),custom.menuSlots.size());}
}
